import{_ as o,o as e,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Practices of Ceph Object Storage in Public Cloud Services - Yu Liyang, China Mobile","description":"","frontmatter":{"title":"Practices of Ceph Object Storage in Public Cloud Services - Yu Liyang, China Mobile","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Public Cloud","Cloud Storage Optimization","Cloud Platform"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Practices_of_Ceph_Object_Storage_in_Public_Cloud_Services_-_Yu_Liyang_China_Mobile.md","filePath":"posts/2019/Practices_of_Ceph_Object_Storage_in_Public_Cloud_Services_-_Yu_Liyang_China_Mobile.md","lastUpdated":1780459816000}'),a={name:"posts/2019/Practices_of_Ceph_Object_Storage_in_Public_Cloud_Services_-_Yu_Liyang_China_Mobile.md"};function n(l,t,s,_,g,c){return e(),i("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： Carolyn、Chana Baba、团队其他成员</p><p><strong>会议主题</strong>： 公共云平台建设与优化讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、公共云平台现状</strong></p><ol><li><strong>平台规模</strong>： 目前云平台已支持政府、企业及内部客户，用户数量不断增加，位于北京、Cointreau和Enchantra，总容量预计超过15PB。</li><li><strong>网络架构</strong>： 采用高速光纤网络，使用Rackware进行用户和数据管理，降低云存储的延迟。</li><li><strong>存储特性</strong>： 用户可比较不同产品，根据需求选择合适的存储方案。目前开发了部分S3特性，如数据包、通知、日志记录和存储类，支持数据在不同存储类之间迁移。</li></ol><p><strong>二、主要议题</strong></p><ol><li><strong>集群扩展问题</strong>： 由于用户上传文件过多，导致资源消耗过快，需要扩展集群。但添加新端口会引发数据重平衡，影响用户体验。</li><li><strong>W模块更新</strong>： 云集群更新时，需要对W模块进行修改，但W模块的STI数量庞大，更新过程耗时较长。</li><li><strong>性能压力</strong>： 生产环境中，主节点的并发请求量超过一万，导致处理速度缓慢，修改元数据时延迟较大。</li></ol><p><strong>三、决策事项</strong></p><ol><li><strong>集群扩展</strong>： 考虑采用其他方案解决集群扩展问题，如增加服务器、优化资源分配等。</li><li><strong>W模块优化</strong>： 优化W模块的更新流程，提高效率。</li><li><strong>性能优化</strong>： 分析主节点性能瓶颈，进行针对性优化。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>技术团队针对集群扩展问题进行调研，提出解决方案。</li><li>技术团队优化W模块更新流程，提高效率。</li><li>性能团队分析主节点性能瓶颈，并提出优化方案。</li></ol><p><strong>五、其他事项</strong></p><ol><li>保持与用户的沟通，了解他们的需求和反馈。</li><li>定期对云平台进行性能测试，确保平台稳定运行。</li></ol><p><strong>关键词</strong>： Ceph, Distributed Storage, Public Cloud, Cloud Storage Optimization, Cloud Platform, Cluster Expansion, W Module, Performance Optimization, S3 Features, Rackware, User Data Management, Latency Reduction, Storage Solutions, Data Migration, STIs, Concurrent Requests, Metadata Latency, Server Augmentation, Resource Allocation, Update Workflow, Efficiency Improvement, Benchmarking</p>',16)])])}const d=o(a,[["render",n]]);export{u as __pageData,d as default};
